// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1) public {
        // first call must happen at a strictly positive timestamp
        t1 = bound(t1, 1, 2 ** 64);
        vm.warp(t1);

        // first fallback call at timestamp t1: admissible (t1 > 0)
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        // second call in the SAME timestamp (any later block)
        vm.roll(block.number + 1);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: after an admissible call, C has recorded t1, so a second
        // call at the same timestamp must revert; the first call must succeed.
        // The mutant never records t1, so its second call succeeds too.
        assertTrue(ok1 && !ok2);
    }
}
